from typing import List

def concatenate(strings: List[str]) -> str:
    """ Concatenate list of strings into a single string.
    Ensure that the function handles both empty and non-empty lists correctly.
    >>> concatenate([])
    ''
    >>> concatenate(['a', 'b', 'c'])
    'abc'
    """
    if not strings:
        return ''
    else:
        return ''.join(strings)

